local Crocheter = {}
local PRODUCTS = {
    simple_cotton_coaster = { name = "Preprosti bombažni podstavek", cottonCost = 1, time = 2, cost = 20, beauty = 12, happiness = 1, description = "Preprosti bombažni podstavek za mizo." },
    lace_trimmed_doily = { name = "Čipkasto obrobljeni krožnik", cottonCost = 2, linenCost = 1, time = 4, cost = 60, beauty = 25, happiness = 1, prestige = 1, description = "Čipkasto obrobljeni krožnik za trgovce." },
    silk_edged_tablecloth = { name = "Svilo obrobljena prt", cottonCost = 2, silkCost = 1, linenCost = 1, time = 7, cost = 180, beauty = 40, happiness = 2, prestige = 4, description = "Svilo obrobljena prt za plemiče." },
    silver_thread_bedspread = { name = "Srebrnonitna posteljna pregrinjala", cottonCost = 3, silkCost = 1, silverCost = 1, linenCost = 1, time = 11, cost = 480, beauty = 55, happiness = 3, prestige = 12, description = "Posteljna pregrinjala s srebrno nitjo za visoke plemiče." },
    gold_edged_altar_cloth = { name = "Zlato obrobljeno oltarno pregrinjalo", cottonCost = 3, silkCost = 2, goldCost = 1, silverCost = 1, linenCost = 1, time = 15, cost = 1100, beauty = 70, happiness = 5, prestige = 24, description = "Oltarno pregrinjalo z zlato obrobo za visoko plemstvo." },
    royal_lace_canopy = { name = "Kraljevska čipkasta neba", cottonCost = 5, silkCost = 4, goldCost = 2, silverCost = 2, jewelCost = 1, pearlCost = 1, time = 22, cost = 2900, beauty = 90, happiness = 11, prestige = 55, description = "Velika kraljevska čipkasta neba z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    crochet_cottage = { name = "Kvačkana koča", cost = { gold = 180, wood = 90, stone = 60, cotton = 6 }, upkeep = 4, qualityBonus = 5 },
    lace_loft = { name = "Čipkarska podstrešje", cost = { gold = 720, wood = 220, stone = 200, silk = 6, linen = 6 }, upkeep = 16, qualityBonus = 18 },
    fine_crochet_atelier = { name = "Finokvačkanski atelje", cost = { gold = 2200, wood = 340, stone = 480, silver = 28, silk = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_lace_palace = { name = "Kraljevska čipkarska palača", cost = { gold = 9200, wood = 580, stone = 720, gold = 55, jewel = 14 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 50 },
}
Crocheter.cottonStock = 16; Crocheter.linenStock = 12; Crocheter.silkStock = 10; Crocheter.silverStock = 6; Crocheter.goldStock = 6; Crocheter.jewelStock = 4; Crocheter.pearlStock = 4
Crocheter.productStock = {}; Crocheter.buildings = {}; Crocheter.maker = nil; Crocheter.activeMaking = {}; Crocheter.totalProducts = 0; Crocheter.dayTimer = 0
function Crocheter.init() Crocheter.cottonStock=16; Crocheter.linenStock=12; Crocheter.silkStock=10; Crocheter.silverStock=6; Crocheter.goldStock=6; Crocheter.jewelStock=4; Crocheter.pearlStock=4; Crocheter.productStock={}; Crocheter.buildings={}; Crocheter.maker=nil; Crocheter.activeMaking={}; Crocheter.totalProducts=0; Crocheter.dayTimer=0; print("[Crocheter] Royal Crocheter System initialized (6 products, 4 buildings)") end
function Crocheter.hireMaker(n,s) s=s or math.random(55,90); local c=420+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Crocheter.maker={name=n or ("Kvačkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kvačkar najet: %s (spretnost: %d)",Crocheter.maker.name,s),"success") end; return true end
function Crocheter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Crocheter.build(id) local ok,e=Crocheter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Crocheter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Crocheter.getQualityBonus() local b=0; for _,bd in ipairs(Crocheter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Crocheter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.cottonCost and Crocheter.cottonStock<(d.cottonCost or 0) then return false,"Premalo bombaža" end; if d.linenCost and Crocheter.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.silkCost and Crocheter.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and Crocheter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Crocheter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Crocheter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and Crocheter.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #Crocheter.buildings==0 then return false,"Potrebna kvačkana koča" end; if not Crocheter.maker then return false,"Potreben kvačkar" end; return true end
function Crocheter.make(pt,qty) qty=qty or 1; local ok,e=Crocheter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.cottonCost then Crocheter.cottonStock=Crocheter.cottonStock-d.cottonCost*qty end; if d.linenCost then Crocheter.linenStock=Crocheter.linenStock-d.linenCost*qty end; if d.silkCost then Crocheter.silkStock=Crocheter.silkStock-d.silkCost*qty end; if d.silverCost then Crocheter.silverStock=Crocheter.silverStock-d.silverCost*qty end; if d.goldCost then Crocheter.goldStock=Crocheter.goldStock-d.goldCost*qty end; if d.jewelCost then Crocheter.jewelStock=Crocheter.jewelStock-d.jewelCost*qty end; if d.pearlCost then Crocheter.pearlStock=Crocheter.pearlStock-d.pearlCost*qty end; local t=d.time; if Crocheter.maker then t=math.max(1,t-math.floor(Crocheter.maker.skill/14)) end; table.insert(Crocheter.activeMaking,{id="crochet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kvačkanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Crocheter.completeMaking(m) local q=1.0+(Crocheter.getQualityBonus()/100); if Crocheter.maker then q=q+(Crocheter.maker.skill/150) end; q=math.min(2.4,q); Crocheter.productStock[m.productType]=(Crocheter.productStock[m.productType] or 0)+m.quantity; Crocheter.totalProducts=Crocheter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Crocheter.maker then Crocheter.maker.itemsMade=Crocheter.maker.itemsMade+m.quantity; if math.random()<0.25 then Crocheter.maker.skill=math.min(100,Crocheter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kvačkanina gotova: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crochet.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function Crocheter.update(dt) if not _G.state then return end; Crocheter.dayTimer=Crocheter.dayTimer+dt; if Crocheter.dayTimer>=30 then Crocheter.dayTimer=0; for i=#Crocheter.activeMaking,1,-1 do local m=Crocheter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Crocheter.completeMaking(m); table.remove(Crocheter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Crocheter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Crocheter.maker then tu=tu+10 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Crocheter.getStats() return {cottonStock=Crocheter.cottonStock,linenStock=Crocheter.linenStock,silkStock=Crocheter.silkStock,silverStock=Crocheter.silverStock,goldStock=Crocheter.goldStock,jewelStock=Crocheter.jewelStock,pearlStock=Crocheter.pearlStock,productStock=Crocheter.productStock,numBuildings=#Crocheter.buildings,hasMaker=Crocheter.maker~=nil,makerName=Crocheter.maker and Crocheter.maker.name or "—",makerSkill=Crocheter.maker and Crocheter.maker.skill or 0,activeMaking=#Crocheter.activeMaking,totalProducts=Crocheter.totalProducts} end
return Crocheter
